/** Assigns a dict key without ever touching the prototype chain. */
export declare function setKey(o: {
    [key: string]: Value;
}, k: string, v: Value): void;
export declare function newDict(entries?: Iterable<[string, Value]>): {
    [key: string]: Value;
};
/** Display form used for string interpolation and str(). */
export declare function str(v: Value): string;
/** Converts to a plain JSON-compatible value (functions become descriptive strings). */
export declare function toJson(v: Value): unknown;
/** Converts parsed JSON into a Value (JSON objects are already safe dicts). */
export declare function fromJson(j: unknown): Value;
export declare function equals(a: Value, b: Value): boolean;
/** Ordering for numbers, strings and (lexicographically) lists. */
export declare function compareValues(a: Value, b: Value): number;
